const alert = document.querySelector('#task-alert');
if (!project.archived) {
  const renameForm = document.querySelector('#rename-form');
  const renameAlert = document.querySelector('#rename-alert');
  renameForm.addEventListener('submit', async event => {
    event.preventDefault();
    const name = renameForm.elements.name.value.trim();
    if (!name) { renameAlert.textContent = 'Project name is required'; renameAlert.hidden = false; return; }
    const result = await fetch(`/api/projects/${encodeURIComponent(id)}/rename`, { method: 'PATCH', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ name }) });
    if (!result.ok) { renameAlert.textContent = 'Project name is required'; renameAlert.hidden = false; return; }
    project.name = name;
    document.querySelector('h1').textContent = name;
    renameForm.elements.name.value = '';
    renameAlert.hidden = true;
  });
}
